insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','clongowes','core','Clongowes Wood College','Clane · County Kildare','building',15,'2026-11-06','Verified geographical reference','Clongowes is the Jesuit college near Clane that Stephen recalls while holding Mulligan’s shaving bowl.','Published coordinate representing the school campus; no position inside the building is inferred.','687f9d992e9c0379f12cd957ab0aec039964776bc03d627c80572c319a124ebd','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','799600ff8227e29dad0cc351f197a83d21f7257ff3f5a35716b2c93145744e63','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Clongowes is the Jesuit college near Clane that Stephen recalls while holding Mulligan’s shaving bowl.","it":"Clongowes è il collegio gesuita presso Clane che Stephen ricorda mentre tiene in mano la ciotola da barba di Mulligan.","fr":"Clongowes est le collège jésuite près de Clane dont Stephen se souvient en tenant le bol à raser de Mulligan.","es":"Clongowes es el colegio jesuita cerca de Clane que Stephen recuerda mientras sostiene el cuenco de afeitar de Mulligan."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:clongowes',1,'clongowes','core',6,'mentioned','Clongowes is the Jesuit college near Clane that Stephen recalls while holding Mulligan’s shaving bowl.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Clongowes is the Jesuit college near Clane that Stephen recalls while holding Mulligan’s shaving bowl.","it":"Clongowes è il collegio gesuita presso Clane che Stephen ricorda mentre tiene in mano la ciotola da barba di Mulligan.","fr":"Clongowes est le collège jésuite près de Clane dont Stephen se souvient en tenant le bol à raser de Mulligan.","es":"Clongowes es el colegio jesuita cerca de Clane que Stephen recuerda mientras sostiene el cuenco de afeitar de Mulligan."}}}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:clongowes:original',1,'1:core:clongowes','original','en','original','He went over to it, held it in his hands awhile, feeling its coolness, smelling the clammy slaver of the lather in which the brush was stuck. So I carried the boat of incense then at Clongowes. I am another now and yet the same. A servant too. A server of a servant.','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Clongowes"],"reviewedAt":"2026-11-06","translationReview":{"it":"No verified reusable version located","fr":"No verified reusable version located","es":"No verified reusable version located"}}'::jsonb) on conflict do nothing;
