insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','muglins','core','Muglins','Off Dalkey Island','area',11,'2026-11-06','Verified geographical reference','The Muglins are the rocks northeast of Dalkey Island, beside which a sail is seen tacking. Their beacon was still unlit in 1904.','Irish Lights coordinate of the beacon/lighthouse on the Muglins rocks, used to identify the rocks. Not the position of the sail. The beacon was unlit in 1904; the first light dates from 1906.','e92380b0f437164c2e27685d7401dfa2164b7b4a5859c36f0b8386071607ae5d','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb',null,'{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"The Muglins are the rocks northeast of Dalkey Island, beside which a sail is seen tacking. Their beacon was still unlit in 1904.","it":"I Muglins sono gli scogli a nord-est di Dalkey Island, presso cui si vede bordeggiare una vela. Nel 1904 il segnale sugli scogli non era ancora luminoso.","fr":"Les Muglins sont les rochers au nord-est de Dalkey Island, près desquels on voit un voilier tirer des bords. Leur balise n’était pas encore éclairée en 1904.","es":"Los Muglins son los escollos al noreste de Dalkey Island, junto a los que se ve una vela virando. En 1904 su baliza todavía no tenía luz."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:muglins',1,'muglins','core',7,'mentioned','The Muglins are the rocks northeast of Dalkey Island, beside which a sail is seen tacking. Their beacon was still unlit in 1904.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"The Muglins are the rocks northeast of Dalkey Island, beside which a sail is seen tacking. Their beacon was still unlit in 1904.","it":"I Muglins sono gli scogli a nord-est di Dalkey Island, presso cui si vede bordeggiare una vela. Nel 1904 il segnale sugli scogli non era ancora luminoso.","fr":"Les Muglins sont les rochers au nord-est de Dalkey Island, près desquels on voit un voilier tirer des bords. Leur balise n’était pas encore éclairée en 1904.","es":"Los Muglins son los escollos al noreste de Dalkey Island, junto a los que se ve una vela virando. En 1904 su baliza todavía no tenía luz."}}}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:muglins:original',1,'1:core:muglins','original','en','original','Eyes, pale as the sea the wind had freshened, paler, firm and prudent. The seas’ ruler, he gazed southward over the bay, empty save for the smokeplume of the mailboat, vague on the bright skyline, and a sail tacking by the Muglins.','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Muglins"],"reviewedAt":"2026-11-06","translationReview":{"it":"No verified reusable version located","fr":"No verified reusable version located","es":"No verified reusable version located"}}'::jsonb) on conflict do nothing;
