insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','mater','core','Mater Misericordiae Hospital','Eccles Street · Dublin','historical',11,'2026-11-06','Verified geographical reference','The Mater is the hospital on Eccles Street that Mulligan mentions while speaking of the deaths he sees during his medical training.','Historical hospital reference from the London School of Hygiene and Tropical Medicine database; representative of the Eccles Street site, not an individual ward.','a98469242609f3828597338c749fb580d039316111919bb82612cf527ce69505','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb',null,'{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"The Mater is the hospital on Eccles Street that Mulligan mentions while speaking of the deaths he sees during his medical training.","it":"Il Mater è l’ospedale di Eccles Street che Mulligan cita parlando delle morti cui assiste durante la formazione medica.","fr":"Le Mater est l’hôpital d’Eccles Street que Mulligan cite en parlant des décès dont il est témoin pendant sa formation médicale.","es":"El Mater es el hospital de Eccles Street que Mulligan menciona al hablar de las muertes que presencia durante su formación médica."}}}'::jsonb) on conflict do nothing;
