insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','dottyville','core','Dottyville · Richmond District Asylum','Grangegorman · Dublin','historical',11,'2026-11-06','Verified geographical reference','Dottyville is Mulligan’s nickname for the Richmond District Asylum at Grangegorman, where Conolly Norman was medical superintendent.','Representative coordinate of the former asylum site. The Dictionary of Irish Biography identifies Norman’s hospital with the novel’s Dottyville. No ward or patient’s position is inferred.','3a585a53995450a93444aebdcc9dba6a6d5491ed497a69bf41e218278aecd4db','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','89175e31712a76e5f3f7100d6e8b797a2925bf76c85a3917c4d127020a1b7073','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Dottyville is Mulligan’s nickname for the Richmond District Asylum at Grangegorman, where Conolly Norman was medical superintendent.","it":"Dottyville è il nome scherzoso usato da Mulligan per il Richmond District Asylum di Grangegorman, diretto da Conolly Norman.","fr":"Dottyville est le surnom employé par Mulligan pour le Richmond District Asylum de Grangegorman, dirigé par Conolly Norman.","es":"Dottyville es el apodo que Mulligan usa para el Richmond District Asylum de Grangegorman, dirigido por Conolly Norman."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:dottyville',1,'dottyville','core',11,'mentioned','Dottyville is Mulligan’s nickname for the Richmond District Asylum at Grangegorman, where Conolly Norman was medical superintendent.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Dottyville is Mulligan’s nickname for the Richmond District Asylum at Grangegorman, where Conolly Norman was medical superintendent.","it":"Dottyville è il nome scherzoso usato da Mulligan per il Richmond District Asylum di Grangegorman, diretto da Conolly Norman.","fr":"Dottyville est le surnom employé par Mulligan pour le Richmond District Asylum de Grangegorman, dirigé par Conolly Norman.","es":"Dottyville es el apodo que Mulligan usa para el Richmond District Asylum de Grangegorman, dirigido por Conolly Norman."}}}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:dottyville:original',1,'1:core:dottyville','original','en','original','—That fellow I was with in the Ship last night, said Buck Mulligan says you have g. p. i. He’s up in Dottyville with Conolly Norman. Genera paralysis of the insane.','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Dottyville"],"reviewedAt":"2026-11-06","translationReview":{"it":"No verified reusable version located","fr":"No verified reusable version located","es":"No verified reusable version located"}}'::jsonb) on conflict do nothing;
