insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','elsinore-model','core','Elsinore · Kronborg model','Helsingør · Denmark','historical',11,'2026-11-06','Verified geographical reference','Haines compares the tower and cliffs to Hamlet’s Elsinore. Kronborg Castle is shown as the documented inspiration for that literary castle.','UNESCO coordinate of the real Kronborg Castle, documented by the castle museum as the inspiration for Hamlet’s Elsinore. This is the real model, not an exact location for the fictional cliffs.','6ef4505c9e805e20dd09f0f969ccde552ffa5cacff70a1d6d25aea6470e13842','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','c1c7e6caa09f1ef04e8868c085e03debc4d7bff249405f506a60e856defccd18','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Haines compares the tower and cliffs to Hamlet’s Elsinore. Kronborg Castle is shown as the documented inspiration for that literary castle.","it":"Haines paragona torre e scogliere all’Elsinore di Amleto. Il castello di Kronborg è rappresentato come modello documentato del castello letterario.","fr":"Haines compare la tour et les falaises à l’Elsinore de Hamlet. Le château de Kronborg est représenté comme le modèle documenté du château littéraire.","es":"Haines compara la torre y los acantilados con el Elsinore de Hamlet. El castillo de Kronborg se representa como modelo documentado del castillo literario."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:elsinore-model',1,'elsinore-model','core',12,'mentioned','Haines compares the tower and cliffs to Hamlet’s Elsinore. Kronborg Castle is shown as the documented inspiration for that literary castle.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Haines compares the tower and cliffs to Hamlet’s Elsinore. Kronborg Castle is shown as the documented inspiration for that literary castle.","it":"Haines paragona torre e scogliere all’Elsinore di Amleto. Il castello di Kronborg è rappresentato come modello documentato del castello letterario.","fr":"Haines compare la tour et les falaises à l’Elsinore de Hamlet. Le château de Kronborg est représenté comme le modèle documenté du château littéraire.","es":"Haines compara la torre y los acantilados con el Elsinore de Hamlet. El castillo de Kronborg se representa como modelo documentado del castillo literario."}}}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:elsinore-model:original',1,'1:core:elsinore-model','original','en','original','—I mean to say, Haines explained to Stephen as they followed, this tower and these cliffs here remind me somehow of Elsinore. That beetles o’er his base into the sea, isn’t it?','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Elsinore"],"reviewedAt":"2026-11-06","translationReview":{"it":"No verified reusable version located","fr":"No verified reusable version located","es":"No verified reusable version located"}}'::jsonb) on conflict do nothing;
