insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','kingstown-harbour','core','Kingstown harbour mouth','Dún Laoghaire','area',11,'2026-11-06','Verified geographical reference','Kingstown is the former name of Dún Laoghaire. Stephen sees the mailboat leaving its harbour; the eastern pier marks one side of the entrance.','The Irish Lights position of the East Pier lighthouse identifies the eastern side of the harbour entrance. It is a fixed geographical reference for the harbour mouth, not a coordinate of the moving mailboat.','8f6786a74f1c8b888e24f7233523e792bb31127e8c681e86139a7cbc7806e099','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','260962c8a9b6548b275ac67fa520c85d4bb50f0f0653b0bd05be1318a4af2b1a','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Kingstown is the former name of Dún Laoghaire. Stephen sees the mailboat leaving its harbour; the eastern pier marks one side of the entrance.","it":"Kingstown è il nome storico di Dún Laoghaire. Stephen vede uscire dal porto il piroscafo postale; il molo orientale delimita un lato dell’imboccatura.","fr":"Kingstown est l’ancien nom de Dún Laoghaire. Stephen voit le paquebot postal sortir du port ; la jetée orientale délimite un côté de l’entrée.","es":"Kingstown es el antiguo nombre de Dún Laoghaire. Stephen ve salir del puerto el vapor correo; el muelle oriental delimita un lado de la entrada."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:kingstown-harbour',1,'kingstown-harbour','core',13,'mentioned','Kingstown is the former name of Dún Laoghaire. Stephen sees the mailboat leaving its harbour; the eastern pier marks one side of the entrance.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Kingstown is the former name of Dún Laoghaire. Stephen sees the mailboat leaving its harbour; the eastern pier marks one side of the entrance.","it":"Kingstown è il nome storico di Dún Laoghaire. Stephen vede uscire dal porto il piroscafo postale; il molo orientale delimita un lato dell’imboccatura.","fr":"Kingstown est l’ancien nom de Dún Laoghaire. Stephen voit le paquebot postal sortir du port ; la jetée orientale délimite un côté de l’entrée.","es":"Kingstown es el antiguo nombre de Dún Laoghaire. Stephen ve salir del puerto el vapor correo; el muelle oriental delimita un lado de la entrada."}}}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:kingstown-harbour:original',1,'1:core:kingstown-harbour','original','en','original','Stephen stood up and went over to the parapet. Leaning on it he looked down on the water and on the mailboat clearing the harbour mouth of Kingstown.
