insert into public.place_descriptions(book_id,place_id,collection,name,area,kind,zoom,checked,status,note,method,position_source_id,narrative_source_id,additional_source_id,metadata) values ('ulisse','magdalen','core','Magdalen College','Oxford','building',15,'2026-11-06','Verified geographical reference','Magdalen is the Oxford college named through Ades in Stephen’s imagined scene of student hazing. The text does not identify Kempthorpe’s rooms with this college.','Published college coordinate. The text identifies Ades as belonging to Magdalen, but does not prove that Kempthorpe’s rooms are within this college. The imagined scene is therefore not assigned action status here.','a4ceae5db4de7b1cecdb05ecfdc555ad557a3ec2a3a5eb7ded7e46280b4eee75','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','5ab7837c7cc4e6503db38f5c28e5deab4081747dbf8134f403c1cf77a22e3ce3','{"positionDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Magdalen is the Oxford college named through Ades in Stephen’s imagined scene of student hazing. The text does not identify Kempthorpe’s rooms with this college.","it":"Magdalen è il collegio di Oxford nominato attraverso Ades nella scena di goliardia immaginata da Stephen. Il testo non identifica con questo collegio gli alloggi di Kempthorpe.","fr":"Magdalen est le collège d’Oxford nommé à travers Ades dans la scène de bizutage imaginée par Stephen. Le texte n’identifie pas les appartements de Kempthorpe à ce collège.","es":"Magdalen es el colegio de Oxford citado a través de Ades en la escena de novatadas imaginada por Stephen. El texto no sitúa los aposentos de Kempthorpe en ese colegio."}}}'::jsonb) on conflict do nothing;
insert into public.place_references(book_id,id,section_id,place_id,collection,ordinal,category,scene_text,source_id,metadata) values ('ulisse','1:core:magdalen',1,'magdalen','core',14,'mentioned','Magdalen is the Oxford college named through Ades in Stephen’s imagined scene of student hazing. The text does not identify Kempthorpe’s rooms with this college.','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','{"explicitCategory":true,"narrativeDescription":{"status":"reviewed","reviewedAt":"2026-11-06","texts":{"en":"Magdalen is the Oxford college named through Ades in Stephen’s imagined scene of student hazing. The text does not identify Kempthorpe’s rooms with this college.","it":"Magdalen è il collegio di Oxford nominato attraverso Ades nella scena di goliardia immaginata da Stephen. Il testo non identifica con questo collegio gli alloggi di Kempthorpe.","fr":"Magdalen est le collège d’Oxford nommé à travers Ades dans la scène de bizutage imaginée par Stephen. Le texte n’identifie pas les appartements de Kempthorpe à ce collège.","es":"Magdalen es el colegio de Oxford citado a través de Ades en la escena de novatadas imaginada por Stephen. El texto no sitúa los aposentos de Kempthorpe en ese colegio."}}}'::jsonb) on conflict do nothing;
insert into public.excerpts(book_id,id,section_id,reference_id,slot,language,type,quote,attribution,text_source_id,rights_source_id,metadata) values ('ulisse','1:core:magdalen:original',1,'1:core:magdalen','original','en','original','Young shouts of moneyed voices in Clive Kempthorpe’s rooms. Palefaces: they hold their ribs with laughter, one clasping another, O, I shall expire! Break the news to her gently, Aubrey! I shall die! With slit ribbons of his shirt whipping the air he hops and hobbles round the table, with trousers down at heels, chased by Ades of Magdalen with the tailor’s shears. A scared calf’s face gilded with marmalade. I don’t want to be debagged! Don’t you play the giddy ox with me!','James Joyce · Ulysses · Shakespeare and Company, Paris, 1922 · Chapter I','526015dd2e238237f14129a76e94b3e4f8e4e27ad07b48d4d4d5a2df2db7dadb','21f5ddc16c42981666952e8d2fe36af645a8542aa0034417c672e91792c00cf9','{"highlightTerms":["Magdalen"],"reviewedAt":"2026-11-06","translationReview":{"it":"No verified reusable version located","fr":"No verified reusable version located","es":"No verified reusable version located"}}'::jsonb) on conflict do nothing;
